--
-- Table structure for table `emergency_rescue`
--

DROP TABLE IF EXISTS `emergency_rescue`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emergency_rescue` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鏁戞彺ID',
  `user_id` bigint NOT NULL COMMENT '姹傛晳鐢ㄦ埛ID',
  `scenic_id` bigint NOT NULL COMMENT '鏅尯ID',
  `rescue_type` varchar(50) NOT NULL COMMENT '鏁戞彺绫诲瀷锛歁EDICAL(鍖荤枟),LOST(璧板け),ACCIDENT(浜嬫晠),OTHER(鍏朵粬)',
  `status` varchar(50) NOT NULL DEFAULT 'PENDING' COMMENT '鏁戞彺鐘舵€侊細PENDING(寰呭鐞?,PROCESSING(澶勭悊涓?,COMPLETED(宸插畬鎴?,CANCELLED(宸插彇娑?',
  `contact_name` varchar(100) NOT NULL COMMENT '鑱旂郴浜哄鍚?,
  `contact_phone` varchar(20) NOT NULL COMMENT '鑱旂郴鐢佃瘽',
  `location` varchar(255) DEFAULT NULL COMMENT '鍏蜂綋浣嶇疆鎻忚堪',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT '绾害',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT '缁忓害',
  `description` text COMMENT '璇︾粏鎻忚堪',
  `emergency_level` varchar(20) DEFAULT 'NORMAL' COMMENT '绱ф€ョ▼搴︼細URGENT(绱ф€?,NORMAL(涓€鑸?',
  `handler_id` bigint DEFAULT NULL COMMENT '澶勭悊浜篒D',
  `handler_name` varchar(100) DEFAULT NULL COMMENT '澶勭悊浜哄鍚?,
  `handle_time` datetime DEFAULT NULL COMMENT '澶勭悊鏃堕棿',
  `complete_time` datetime DEFAULT NULL COMMENT '瀹屾垚鏃堕棿',
  `handle_notes` text COMMENT '澶勭悊澶囨敞',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `deleted_at` datetime DEFAULT NULL COMMENT '杞垹闄ゆ椂闂?,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_scenic_id` (`scenic_id`),
  KEY `idx_status` (`status`),
  KEY `idx_rescue_type` (`rescue_type`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `fk_rescue_scenic` FOREIGN KEY (`scenic_id`) REFERENCES `scenic_spots` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_rescue_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='绱ф€ユ晳鎻磋〃';
/*!40101 SET character_set_client = @saved_cs_client */;

