--
-- Table structure for table `itineraries`
--

DROP TABLE IF EXISTS `itineraries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `itineraries` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '琛岀▼ID',
  `itinerary_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '琛岀▼缂栧彿',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '琛岀▼鏍囬',
  `travel_date` date NOT NULL COMMENT '鍑鸿鏃ユ湡',
  `start_time` time DEFAULT NULL COMMENT '寮€濮嬫椂闂?,
  `end_time` time DEFAULT NULL COMMENT '缁撴潫鏃堕棿',
  `days` int NOT NULL DEFAULT '1' COMMENT '澶╂暟',
  `party_size` int NOT NULL DEFAULT '1' COMMENT '浜烘暟',
  `preferences` json DEFAULT NULL COMMENT '鍋忓ソ璁剧疆',
  `total_distance` decimal(8,2) DEFAULT NULL COMMENT '鎬昏窛绂伙紙km锛?,
  `total_duration` int DEFAULT NULL COMMENT '鎬绘椂闀匡紙鍒嗛挓锛?,
