INSERT INTO `news` (`id`, `title`, `summary`, `content`, `category`, `covers`, `scenic_id`, `author_id`, `views`, `status`, `publish_time`, `created_at`, `updated_at`, `activity_id`, `source`) VALUES (8,'銆婂叚鐩樻按鐨?鈥滃煄甯傜豢瀹濈煶鈥濓紒鏄庢箹婀垮湴锛氬厤璐归€涳紝鍦ㄥ煄甯傞噷閭傞€呰嚜鐒剁枟鎰堬綖銆?,'','鏄庢箹鍥藉婀垮湴鍏洯锛屾槸鍏洏姘村競涓績鐨?鈥滅敓鎬佺澧冣€濄€傛緞婢堟箹姘淬€佽懕閮佹琚笌鐜颁唬妗ユ鐩告槧鎴愯叮锛屾极姝ュ叾涓紝鏃㈣兘鎰熷彈婀垮湴鐢熸€佺殑娓呭菇闈欒哀锛屽張鑳藉湪 鈥滃煄甯傜箒鍗庘€?涓?鈥滆嚜鐒堕噹瓒ｂ€?闂磋嚜鐢卞垏鎹€傞キ鍚庢暎姝ャ€佸懆鏈噹椁愶紝鎴栨槸鍗曠函閫冪鍠у殻 鈥滃惛姘р€濓紝杩欓噷閮芥槸鐤楁剤韬績鐨勭粷浣充箣閫夛綖','鏅偣鎺ㄨ崘',NULL,5,18,0,'published','2025-10-19 05:28:54','2025-10-19 05:28:54','2025-10-19 05:28:54',NULL,'manual'),(9,'銆婂厤璐规矇娴稿紡浣撻獙锛佹按鍩庡彜闀囷細鐧惧勾琛楀贩閲岋紝钘忕潃鍏洏姘存渶娴撶殑鐑熺伀涓庢皯淇楋綖銆?,'','鍏嶈垂寮€鏀剧殑姘村煄鍙ら晣锛屾槸鍏洏姘村巻鍙叉枃鍖栫殑 鈥滄椿鎬佸崥鐗╅鈥濄€傞潚鐭虫澘璺€佸鍙ゅ缓绛戦晫鍒荤潃宀佹湀鐥曡抗锛岃澶存皯淇楄〃婕旂儹闂归矞娲伙紝鐗硅壊灏忓悆鎽婏紙濡傜儥閿呫€佺緤鑲夌矇锛夐姘旂洿閽婚蓟鑵旓紝鎵嬪伐鑹哄搧搴楁憜婊＄簿宸х殑闈為仐鐗╀欢鈥︹€?璧拌繘杩欓噷锛屼豢浣涚┛瓒婃椂鍏夛紝涓€绔欏紡鎰熷彈鍏洏姘寸殑鐑熺伀姘斾笌姘戜織榄呭姏锝?,'鏃呮父鏀荤暐',NULL,4,19,0,'published','2025-10-19 05:29:29','2025-10-19 05:29:29','2025-10-19 05:29:29',NULL,'manual'),(10,'銆婇棷杩?鈥滆吹宸炲眿鑴娾€?绔ヨ瘽锛佷箤钂欏ぇ鑽夊師锛氳崏鍘熴€侀鐢点€佺墽鍦哄悓妗嗭紝闅忔墜鎷嶉兘鏄?鈥滃ぉ鑺辨澘绾р€?澶х墖锝炪€?,'','琚獕涓?鈥滆吹宸炲眿鑴娾€?鐨勪箤钂欏ぇ鑽夊師锛屾妸 鈥滈珮灞辫崏鍘熺殑杈介様 + 椋庣數鍦虹殑绉戞妧鎰?+ 鐗у満鐨勬偁鐒垛€?瀹岀編铻嶅悎銆傜珯鍦ㄨ崏鍘熶笂锛屽法鍨嬮鐢靛彾鐗囩紦缂撹浆鍔紝鎴愮兢鐗涚緤鎮犵劧韪辨锛屾棤杈硅崏鐢稿湪鐪煎墠閾哄睍锛堢鍐洿鏄鹃噾榛勮媿鑼級銆傛潵杩欓噷闇茶惀銆佽拷鏃ュ嚭鏃ヨ惤锛屼豢浣涗竴澶存墡杩涜嚜鐢卞張澹編鐨勭璇濅笘鐣岋綖','鏅偣鎺ㄨ崘',NULL,3,16,0,'published','2025-10-19 05:30:25','2025-10-19 05:30:25','2025-10-19 05:30:25',NULL,'manual'),(11,'銆婂叏骞翠笉閲嶆牱鐨勫揩涔愶紒鐜夎垗鍥藉妫灄鍏洯锛氬師濮嬫．鏋椼€佸崕鍗楁渶澶ф粦闆満锛屾壙鍖呬綘鍥涘鐨勬湡寰咃綖銆?,'','钘忕潃 鈥滃師濮嬫．鏋?+ 鍗庡崡鏈€澶ф粦闆満鈥?鐨勭帀鑸嶅浗瀹舵．鏋楀叕鍥紝鍫О 鈥滃洓瀛ｅ疂钘忓湴鈥濓紒鏄ュ彲鎺㈡．鏋楅噹鑺便€佸鑳介伩鏆戝惛姘с€佺璧忓眰鏋楀敖鏌擄紝鍐鏇磋兘涓€澶存墡杩涙灄娴烽洩鍘燂紝鍦ㄥ崕鍗楁渶澶ф粦闆満浣撻獙 鈥滈洩涓婇椹扳€?鐨勫埡婵€銆傝嚜鐒剁埍濂借€呫€佹粦闆彂鐑у弸鈥︹€?涓嶅悓瀛ｈ妭鏉ワ紝閮借兘鏀惰幏涓撳睘蹇箰锝?,'鏃呮父鏀荤暐',NULL,2,17,0,'published','2025-10-19 05:31:00','2025-10-19 05:31:00','2025-10-19 05:31:00',NULL,'manual'),(12,'銆婂垵鍐荡涓€鍦?鈥滄鈥?濂戒箣绾︼紒姊呰姳灞遍鏅尯锛氬北姘翠綔骞曪紝瀵掓寰呮斁锛岃瘲鎰忓€兼媺婊★綖銆?,'','浣滀负鍥藉 4A 绾ф櫙鍖猴紝姊呰姳灞遍鏅尯浠?鈥滃北姘寸涓?+ 瑗垮崡璧忔鑳滃湴鈥?钁楃О銆傚綋涓嬫椂鑺傦紝灞遍棿姊呮灄姝ｉ厺閰跨潃 鈥滃偛楠ㄧ唤鏀锯€?鐨勬氮婕紝灞辨按浜戦浘涓庢湨鑳ф褰变氦缁囷紝瀹涘澶╃劧姘村ⅷ鐢诲嵎銆傛棤璁烘槸鎻愬墠鏉ヨ荡 鈥滃瘨姊呬箣绾︹€濓紝杩樻槸婕父灞遍棿鍚告哀娲楄偤锛岄兘鑳借В閿佸叚鐩樻按鍒濆啲鐙湁鐨勮瘲鎰忎笌鏉惧紱锝?,'鏅偣鎺ㄨ崘',NULL,1,12,2,'published','2025-10-19 05:31