  `weather` varchar(20) DEFAULT NULL COMMENT '澶╂皵鎯呭喌',
  `is_weekend` tinyint DEFAULT '0' COMMENT '鏄惁鍛ㄦ湯',
  `is_holiday` tinyint DEFAULT '0' COMMENT '鏄惁鑺傚亣鏃?,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
