INSERT INTO `site_configs` (`id`, `config_key`, `config_json`, `created_at`, `updated_at`) VALUES (1,'landing','{\"stats\":[{\"id\":1,\"label\":\"棰勬祴鍑嗙‘鐜嘰",\"target\":96,\"suffix\":\"%\"},{\"id\":2,\"label\":\"瑕嗙洊鏅尯\",\"target\":5,\"suffix\":\"+\"},{\"id\":3,\"label\":\"骞冲潎鍝嶅簲\",\"target\":180,\"suffix\":\"ms\"}],\"features\":[{\"id\":1,\"icon\":\"馃敭\",\"title\":\"鏅鸿兘瀹㈡祦棰勬祴\",\"description\":\"鍩轰簬LSTM-ARIMA娣峰悎妯″瀷锛岀簿鍑嗛娴嬫櫙鍖烘湭鏉ュ娴佽秼鍔縗"},{\"id\":2,\"icon\":\"馃椇锔廫",\"title\":\"琛岀▼瑙勫垝\",\"description\":\"AI绠楁硶浼樺寲娓歌璺嚎锛岄伩寮€楂樺嘲鑺傜渷鏃堕棿\"},{\"id\":3,\"icon\":\"馃搳\",\"title\":\"瀹炴椂鏁版嵁鍒嗘瀽\",\"description\":\"3D鍙鍖栧ぇ灞忥紝瀹炴椂鐩戞帶鏅尯杩愯惀鐘舵€乗"}],\"highlights\":[{\"id\":1,\"badge\":\"鍦板煙閫傞厤\",\"title\":\"鍏洏姘存湰鍦板寲\",\"desc\":\"缁撳悎鍦板舰姘斿€?鑺傚亣鏃?姘戞棌鑺傚簡绛夊湪鍦扮壒寰佽繘琛屾ā鍨嬭皟浼榎",\"points\":[\"鉁?姘斿€欎笌瀛ｈ妭鐗瑰緛宸ョ▼\",\"鉁?鏅尯鎵胯浇涓庡嚭鍏ュ彛娴佸悜\",\"鉁?鏈湴浜ら€?鑺傚簡浜嬩欢娉ㄥ叆\"]},{\"id\":2,\"badge\":\"AI 棰勬祴\",\"title\":\"娣峰悎鏃跺簭绠楁硶\",\"desc\":\"LSTM 脳 ARIMA 鍙犲姞鍋囨棩澧炲己锛岀煭涓湡瀹㈡祦瓒嬪娍鏇寸ǔ\",\"points\":[\"鉁?96%+ 楠岃瘉闆嗗噯纭巼鐩爣\",\"鉁?灏忔牱鏈満鏅瞾妫掓€т紭鍖朶",\"鉁?棰勬祴鍖洪棿涓庣疆淇″害杈撳嚭\"]},{\"id\":3,\"badge\":\"3D 鍙鍖朶",\"title\":\"娌夋蹈寮忔暟鎹ぇ灞廫",\"desc\":\"涓夌淮鍦板浘涓庡疄鏃舵寚鏍囪仈鍔紝鐑偣/鎷ユ尋鍖轰竴鐩簡鐒禱",\"points\":[\"鉁?鐑偣鐑姏/浜烘祦杞ㄨ抗鑱斿姩\",\"鉁?闃堝€奸璀︿笌娑堟伅鎺ㄩ€乗",\"鉁?澶氱粓绔嚜閫傚簲灞曠ず\"]}],\"scenarios\":[{\"id\":1,\"icon\":\"馃殾\",\"title\":\"楂樺嘲閿欏嘲涓庡娴乗",\"desc\":\"鑺傚亣鏃ユ彁鍓嶉璀﹀苟浼樺寲鍏ュ洯鏃舵锛屽噺灏戞嫢鍫礬"},{\"id\":2,\"icon\":\"馃殞\",\"title\":\"浜ら€氭帴椹崇紪鎺抃",\"desc\":\"棰勬祴瀹㈡祦宄拌胺锛屽姩鎬佽皟鏁村叕浜や笌鎽嗘浮杞﹂娆"},{\"id\":3,\"icon\":\"馃洝锔廫",\"title\":\"鎵胯浇涓庡畨鍏ㄤ繚闅淺",\"desc\":\"瓒呴槇鍊煎疄鏃跺憡璀︼紝鑱斿姩瀹変繚涓庡箍鎾彁绀篭"}],\"testimonials\":[{\"content\":\"棰勬祴缁撴灉鍩烘湰璐村悎瀹為檯锛屾垜浠殑娓稿鎶曡瘔鐜囨槑鏄句笅闄嶃€俓",\"author\":\"姘村煄鍙ら晣\",\"role\":\"杩愯惀缁忕悊\"},{\"content\":\"楂樺嘲鏃剁殑鎺ラ┏杞﹁締璋冨害鏁堢巼鎻愬崌浜嗕笉灏戙€俓",\"author\":\"甯傛枃鏃呭眬\",\"role\":\"鏁版嵁绉慭"},{\"content\":\"璺嚎瑙勫垝瀵归伩寮€鎺掗槦寰堟湁甯姪锛屾父瀹綋楠屾洿濂戒簡銆俓",\"author\":\"鐜夎垗妫灄鍏洯\",\"role\":\"娓稿鏈嶅姟\"}]}','2025-10-11 20:43:42','2025-11-05 15:17:21');
